use serde::{Deserialize, Serialize};

/// Read-only projections generated by the node, never caller-provided shell scripts.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum GitRead {
    State,
    Branches {
        fallback: String,
    },
    History {
        revision: Option<String>,
        offset: u32,
        search: String,
    },
    Files {
        commit: String,
    },
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct GitOutput {
    pub exit_code: Option<i32>,
    pub timed_out: bool,
    pub output: String,
}
